import { rateLimitOf, retryAfterOf } from "./errors.js";
import type { RequestEvent, ResponseHandler } from "./events.js";
import { attemptStore } from "./http.js";

/** A multipart body is the file's bytes; the event carries what it was instead. */
function summariseBody(body: BodyInit | null | undefined): unknown {
  if (body === null || body === undefined) return null;
  if (typeof body === "string") {
    try {
      return JSON.parse(body);
    } catch {
      return body;
    }
  }
  if (typeof FormData !== "undefined" && body instanceof FormData) {
    const file = body.get("file");
    if (file instanceof Blob) {
      return {
        filename: typeof File !== "undefined" && file instanceof File ? file.name : null,
        mimeType: file.type || null,
        sizeBytes: file.size,
      };
    }
    return "<form data>";
  }
  return "<binary>";
}

function parseOrText(text: string): unknown {
  if (text === "") return null;
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

/**
 * Wraps a fetch so every attempt reaches `onResponse`.
 *
 * Around `fetch` rather than the runtime's middleware, which never sees a request
 * that failed to reach the server — the `status: null` case. The body is read
 * through a clone so the generated core still gets an unread one.
 */
export function observingFetch(inner: typeof fetch, onResponse: ResponseHandler): typeof fetch {
  return async (input, init) => {
    const startedAt = Date.now();
    const method = init?.method ?? "GET";
    const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
    const headers = new Headers(init?.headers);
    const idempotencyKey = headers.get("Idempotency-Key");
    const attempt = attemptStore.getStore() ?? 1;

    // Never let a caller's own callback — or building the event for it — break the
    // request it is only watching. `build` runs inside the try for that reason: as
    // an argument it would throw outside, the runtime would see a rejection, and a
    // send that actually succeeded would be retried.
    const emit = (build: () => RequestEvent) => {
      try {
        onResponse(build());
      } catch {
        /* the hook observes; it does not get a vote */
      }
    };

    let response: Response;
    try {
      response = await inner(input, init);
    } catch (cause) {
      emit(() => ({
        method,
        url,
        status: null,
        requestBody: summariseBody(init?.body),
        responseBody: null,
        requestId: null,
        idempotencyKey,
        rateLimit: null,
        retryAfterSeconds: null,
        elapsedMs: Date.now() - startedAt,
        attempt,
        transportError: cause instanceof Error ? cause.message : String(cause),
      }));
      throw cause;
    }

    let responseBody: unknown = null;
    try {
      responseBody = parseOrText(await response.clone().text());
    } catch {
      // A body that cannot be re-read is not worth failing the call over.
    }

    emit(() => ({
      method,
      url,
      status: response.status,
      requestBody: summariseBody(init?.body),
      responseBody,
      requestId: response.headers.get("x-request-id"),
      idempotencyKey,
      rateLimit: rateLimitOf(response),
      retryAfterSeconds: retryAfterOf(response),
      elapsedMs: Date.now() - startedAt,
      attempt,
      transportError: null,
    }));

    return response;
  };
}
