import { ApiErrorCodeEnum } from "./generated/models/ApiError.js";
import { ResponseError } from "./generated/runtime.js";

/**
 * The documented codes, plus any string. The catalogue grows every release, so an
 * older SDK must pass a code it has never seen through to the caller rather than
 * reject it — `(string & {})` keeps autocomplete on the known ones.
 */
export type MsgEasyErrorCode =
  | (typeof ApiErrorCodeEnum)[keyof typeof ApiErrorCodeEnum]
  | (string & {});

export const ErrorCode = ApiErrorCodeEnum;

/**
 * Everything this SDK raises. Catch this to catch all of it; branch on the
 * subclasses, or on `code`, to tell the cases apart.
 */
export class MsgEasyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MsgEasyError";
  }
}

/** A refusal the API described. Branch on `code`, never on `message` or `status`. */
export class APIError extends MsgEasyError {
  readonly code: MsgEasyErrorCode;
  readonly status: number;
  readonly requestId: string | null;
  readonly details: unknown;
  readonly retryAfterSeconds: number | null;
  readonly rateLimit: RateLimit | null;

  constructor(init: {
    code: MsgEasyErrorCode;
    status: number;
    message: string;
    requestId: string | null;
    details?: unknown;
    retryAfterSeconds?: number | null;
    rateLimit: RateLimit | null;
  }) {
    super(init.message);
    this.name = new.target.name;
    this.code = init.code;
    this.status = init.status;
    this.requestId = init.requestId;
    this.details = init.details;
    this.retryAfterSeconds = init.retryAfterSeconds ?? null;
    this.rateLimit = init.rateLimit;
  }
}

/** The key is missing, malformed, expired or revoked. */
export class AuthenticationError extends APIError {}
/** The key is valid but its scopes do not cover this route. */
export class PermissionDeniedError extends APIError {}
/** Too many requests for this key. `retryAfterSeconds` says how long to wait. */
export class RateLimitError extends APIError {}
/** An allowance is spent and nothing refills until the cycle turns. */
export class QuotaError extends APIError {}
/** The account is not ready: no Verify template, no sender, no WhatsApp connection. */
export class SetupRequiredError extends APIError {}
/** No such resource, or it belongs to another account — deliberately the same answer. */
export class NotFoundError extends APIError {}
/** The request itself is wrong; `message` says how. */
export class InvalidRequestError extends APIError {}
/** The key was reused — still in flight, or for a different body. */
export class IdempotencyError extends APIError {}
/** Outside the 24-hour window, so only a template may be sent. */
export class WindowExpiredError extends APIError {}
/** The template cannot be used or changed in its current state. */
export class TemplateError extends APIError {}
/** Meta refused or failed. */
export class MetaError extends APIError {}
/** A dependency is down. Retryable. */
export class ServiceUnavailableError extends APIError {}
/** A `msg_test_` key cannot reach this route. */
export class TestKeyError extends APIError {}

/**
 * Which class a code raises. **Identical to the Python SDK's `_CODE_ERRORS`** — one
 * entry out of step is a divergence nothing would catch, so change both together.
 * A code absent from here raises plain `APIError`, which is how a release older than
 * the catalogue still surfaces a new refusal.
 */
const CODE_ERRORS: Record<string, typeof APIError> = {
  invalid_api_key: AuthenticationError,
  insufficient_scope: PermissionDeniedError,
  rate_limited: RateLimitError,
  quota_exceeded: QuotaError,
  key_limit_reached: QuotaError,
  spend_cap_reached: QuotaError,
  verify_not_configured: SetupRequiredError,
  no_sender: SetupRequiredError,
  whatsapp_not_connected: SetupRequiredError,
  not_found: NotFoundError,
  invalid_request: InvalidRequestError,
  unsupported_media_type: InvalidRequestError,
  media_too_large: InvalidRequestError,
  idempotency_conflict: IdempotencyError,
  window_expired: WindowExpiredError,
  template_not_approved: TemplateError,
  template_name_taken: TemplateError,
  template_not_editable: TemplateError,
  template_category_not_allowed: TemplateError,
  meta_error: MetaError,
  service_unavailable: ServiceUnavailableError,
  test_key_not_allowed: TestKeyError,
};

/** Refused here, before anything was sent. The request is wrong, not the answer. */
export class ValidationError extends MsgEasyError {
  constructor(message: string) {
    super(message);
    this.name = "ValidationError";
  }
}

/**
 * No response arrived at all — DNS, a reset connection, a timeout. The operation
 * may or may not have run, which is why a retry reuses the idempotency key.
 */
export class APIConnectionError extends MsgEasyError {
  override readonly cause: unknown;

  constructor(message: string, cause?: unknown) {
    super(message);
    this.name = "APIConnectionError";
    this.cause = cause;
  }
}

/**
 * A non-2xx that did not carry the documented envelope — almost always something
 * other than the API answering, such as a proxy's HTML error page. Carries no
 * `code` at all: a caller branching on one must never be handed an absence where a
 * code belongs.
 */
export class BadEnvelopeError extends MsgEasyError {
  readonly status: number;
  readonly requestId: string | null;
  readonly body: string;

  constructor(status: number, body: string, requestId: string | null) {
    super(`The API returned ${status} without a recognisable error body.`);
    this.name = "BadEnvelopeError";
    this.status = status;
    this.requestId = requestId;
    this.body = body;
  }
}

/**
 * What is left of the key's per-minute allowance.
 *
 * Absent or complete, never partial: the API sends all three headers together or
 * none at all, so `null` means the limiter never charged this response — not that
 * nothing is left.
 */
export interface RateLimit {
  limit: number;
  remaining: number;
  resetSeconds: number;
}

function numberHeader(response: Response, name: string): number | null {
  const raw = response.headers.get(name);
  if (raw === null) return null;
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

export function rateLimitOf(response: Response): RateLimit | null {
  const limit = numberHeader(response, "x-ratelimit-limit");
  const remaining = numberHeader(response, "x-ratelimit-remaining");
  const resetSeconds = numberHeader(response, "x-ratelimit-reset");

  if (limit === null || remaining === null || resetSeconds === null) return null;
  return { limit, remaining, resetSeconds };
}

/** `0` is a real answer — retry now — so only a negative or unparseable value is absent. */
export function retryAfterOf(response: Response): number | null {
  const raw = response.headers.get("retry-after");
  if (raw === null || raw === "") return null;
  const seconds = Number(raw);
  return Number.isFinite(seconds) && seconds >= 0 ? seconds : null;
}

/**
 * Turns the generated `ResponseError` — which carries the response unread — into a
 * typed error. The two guards are the only checking the SDK does: the body must be
 * JSON and must carry a `code`.
 *
 * Anything that is not a `ResponseError` never reached a response at all, so it
 * becomes `APIConnectionError` rather than passing through as the runtime's own.
 */
export async function toMsgEasyError(error: unknown): Promise<unknown> {
  if (!(error instanceof ResponseError)) {
    if (error instanceof MsgEasyError) return error;
    const message = error instanceof Error ? error.message : String(error);
    return new APIConnectionError(message, error);
  }

  const response = error.response;
  const requestId = response.headers.get("x-request-id");
  const text = await response.text().catch(() => "");

  let body: unknown;
  try {
    body = JSON.parse(text);
  } catch {
    return new BadEnvelopeError(response.status, text, requestId);
  }

  // `JSON.parse` happily returns null, a number or an array, none of which carry a
  // `code` — and reading one off null throws where the caller expects our error.
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    return new BadEnvelopeError(response.status, text, requestId);
  }

  const envelope = body as { code?: unknown; message?: unknown; details?: unknown };
  if (typeof envelope.code !== "string") {
    return new BadEnvelopeError(response.status, text, requestId);
  }

  const Cls = CODE_ERRORS[envelope.code] ?? APIError;
  return new Cls({
    code: envelope.code,
    status: response.status,
    message: typeof envelope.message === "string" ? envelope.message : response.statusText,
    requestId,
    details: envelope.details,
    retryAfterSeconds: retryAfterOf(response),
    rateLimit: rateLimitOf(response),
  });
}
