import { createHmac, timingSafeEqual } from "node:crypto";

/**
 * The header the API signs deliveries with.
 *
 * Lower-case because that is the one spelling every receiver can look up: Node
 * lower-cases inbound header names, so `req.headers["X-Msgeasy-Signature"]` is
 * always `undefined`, while `Headers.get` and Express's `req.header` ignore case.
 * The sender has its own copy and is unaffected.
 */
export const SIGNATURE_HEADER = "x-msgeasy-signature";

const DEFAULT_TOLERANCE_SECONDS = 300;

/** Why a delivery was refused. `ok` alone cannot be logged or acted on. */
export type SignatureFailure =
  | "no_secret_configured"
  | "missing_header"
  | "malformed_header"
  | "stale_timestamp"
  | "bad_signature";

export type SignatureResult = { ok: true } | { ok: false; reason: SignatureFailure };

/** Anything a framework calls a header bag, plus the bare value. */
export type SignatureHeaders =
  | string
  | string[]
  | undefined
  | null
  | Headers
  | Record<string, string | string[] | undefined>;

/**
 * Pulls the signature out of whatever the caller passed.
 *
 * Done here rather than by the caller because the lookup is where this goes wrong:
 * a plain Node header object is keyed lower-case, a `Headers` is case-insensitive,
 * and getting it wrong fails silently as an unsigned delivery.
 */
function headerValue(headers: SignatureHeaders): string | string[] | undefined | null {
  if (headers === undefined || headers === null) return headers;
  if (typeof headers === "string" || Array.isArray(headers)) return headers;
  if (typeof Headers !== "undefined" && headers instanceof Headers) {
    return headers.get(SIGNATURE_HEADER);
  }
  for (const [name, value] of Object.entries(headers)) {
    if (name.toLowerCase() === SIGNATURE_HEADER) return value;
  }
  return undefined;
}

/**
 * Whether a delivery really came from us and is recent.
 *
 * `body` must be the **raw** request body, before any JSON parsing — re-serialising
 * changes the bytes and the signature will not match.
 *
 * The timestamp is inside the signed payload, so an old capture cannot be replayed
 * once it falls outside the tolerance.
 *
 * Pass the whole header bag: a delivery that omits the header — or sends it twice,
 * which an attacker can — is refused rather than throwing inside a handler.
 */
export function verifyWebhookSignature(
  body: string,
  headers: SignatureHeaders,
  secret: string,
  options: { toleranceSeconds?: number; nowMs?: number } = {},
): SignatureResult {
  if (!secret) return { ok: false, reason: "no_secret_configured" };

  const header = headerValue(headers);
  // An array means the header arrived twice. Two signatures is not one delivery to trust.
  if (Array.isArray(header)) return { ok: false, reason: "malformed_header" };
  if (typeof header !== "string" || header === "") return { ok: false, reason: "missing_header" };

  const tolerance = options.toleranceSeconds ?? DEFAULT_TOLERANCE_SECONDS;
  const now = Math.floor((options.nowMs ?? Date.now()) / 1000);

  const pairs = header.split(",").map((piece) => {
    const [key, ...rest] = piece.trim().split("=");
    return [key, rest.join("=")] as const;
  });

  // Two deliveries joined into one header comes through as a single comma-joined
  // string, not an array — and a `Map` would silently keep the last pair, so a
  // bogus signature followed by a valid one would pass.
  if (pairs.filter(([key]) => key === "v1").length !== 1) {
    return { ok: false, reason: "malformed_header" };
  }
  const parts = new Map(pairs);

  const timestamp = Number(parts.get("t"));
  const received = parts.get("v1");
  if (!Number.isFinite(timestamp) || !received) return { ok: false, reason: "malformed_header" };
  if (Math.abs(now - timestamp) > tolerance) return { ok: false, reason: "stale_timestamp" };

  const expected = createHmac("sha256", secret).update(`${timestamp}.${body}`).digest("base64");
  const a = Buffer.from(expected);
  const b = Buffer.from(received);
  // Lengths must match first — `timingSafeEqual` throws when they differ.
  if (a.length !== b.length || !timingSafeEqual(a, b)) {
    return { ok: false, reason: "bad_signature" };
  }
  return { ok: true };
}
