import { type RateLimit, rateLimitOf } from "./errors.js";
import type { ResponseHandler } from "./events.js";
import type { TemplatesListStatusEnum } from "./generated/apis/index.js";
import { MediaApi, MessagesApi, TemplatesApi, VerifyApi } from "./generated/apis/index.js";
import type {
  CheckVerificationInput,
  CreateTemplateInput,
  Media,
  SendMessageInput,
  StartVerificationInput,
  Template,
  TemplateList,
  UpdateTemplateInput,
} from "./generated/models/index.js";
import { Configuration, type Middleware } from "./generated/runtime.js";
import {
  type CallOptions,
  callInit,
  DEFAULT_TIMEOUT_MS,
  type ReadOptions,
  timedFetch,
  withRetries,
} from "./http.js";
import { observingFetch } from "./observe.js";
import { VERSION } from "./version.js";

const DEFAULT_BASE_URL = "https://api.msgeasy.com";

export interface MsgEasyOptions {
  baseUrl?: string;
  timeoutMs?: number;
  /** Called once per attempt, successful or not. See `RequestEvent`. */
  onResponse?: ResponseHandler;
}

export interface TemplateListQuery {
  /** 1-100. Defaults to 20. */
  limit?: number;
  /** Only templates in this state. */
  status?: TemplatesListStatusEnum;
  /** Only templates changed since this instant, which is what makes polling cheap. */
  updatedAfter?: Date | string;
  /** The last `id` of the previous page. `listAll` sets this for you. */
  startingAfter?: string;
}

/** `updatedAfter` reaches the wire as ISO 8601; the API coerces a string back to a date. */
function templateQuery(query: TemplateListQuery) {
  const { updatedAfter, ...rest } = query;
  return {
    ...rest,
    ...(updatedAfter
      ? { updatedAfter: updatedAfter instanceof Date ? updatedAfter.toISOString() : updatedAfter }
      : {}),
  };
}

export class MsgEasy {
  /**
   * What the most recent response reported — whichever call that was, so a pacing
   * signal rather than a per-call fact. `null` on a key with no limit.
   */
  rateLimit: RateLimit | null = null;

  readonly verify: VerifyNamespace;
  readonly messages: MessagesNamespace;
  readonly media: MediaNamespace;
  readonly templates: TemplatesNamespace;

  constructor(apiKey: string, options: MsgEasyOptions = {}) {
    if (!apiKey) throw new Error("An API key is required.");

    const baseUrl = options.baseUrl ?? DEFAULT_BASE_URL;
    const timed = timedFetch(options.timeoutMs ?? DEFAULT_TIMEOUT_MS);
    const fetchApi = options.onResponse ? observingFetch(timed, options.onResponse) : timed;
    const headers = {
      "x-api-key": apiKey,
      "User-Agent": `msgeasy-node/${VERSION}`,
    };

    // Recorded rather than returned, so a caller can pace itself without every
    // method having to hand back a wrapper object.
    const recordRateLimit: Middleware = {
      post: async ({ response }) => {
        this.rateLimit = rateLimitOf(response);
      },
    };

    const config = new Configuration({
      basePath: baseUrl,
      fetchApi,
      middleware: [recordRateLimit],
      headers,
    });

    this.verify = new VerifyNamespace(new VerifyApi(config));
    this.messages = new MessagesNamespace(new MessagesApi(config));
    this.media = new MediaNamespace(new MediaApi(config));
    this.templates = new TemplatesNamespace(new TemplatesApi(config));
  }
}

class VerifyNamespace {
  constructor(private readonly api: VerifyApi) {}

  start(body: StartVerificationInput, options: CallOptions = {}) {
    return withRetries(
      (key) => this.api.verifyStart({ startVerificationInput: body }, callInit(key, options)),
      { write: true, callOptions: options },
    );
  }

  check(body: CheckVerificationInput, options: CallOptions = {}) {
    return withRetries(
      (key) => this.api.verifyCheck({ checkVerificationInput: body }, callInit(key, options)),
      { write: true, callOptions: options },
    );
  }
}

class MessagesNamespace {
  constructor(private readonly api: MessagesApi) {}

  send(body: SendMessageInput, options: CallOptions = {}) {
    return withRetries(
      (key) => this.api.messagesSend({ sendMessageInput: body }, callInit(key, options)),
      { write: true, callOptions: options },
    );
  }

  get(id: string, options: ReadOptions = {}) {
    return withRetries(() => this.api.messagesGet({ id }, callInit(undefined, options)));
  }
}

class MediaNamespace {
  constructor(private readonly api: MediaApi) {}

  upload(file: Blob, filename?: string, options: CallOptions = {}): Promise<Media> {
    return withRetries(
      (key) => {
        // The generated core appends the file with no filename, and the API stores
        // that name (`media/routes.ts:173`) and hashes it into the idempotency
        // fingerprint (`plugins/idempotency.ts:190`). Sending a named body instead
        // keeps the name without giving up the generated request: auth, middleware,
        // error mapping and the response parse all still come from the runtime.
        const form = new FormData();
        form.append("file", file, filename);
        return this.api.mediaUpload({ file }, callInit(key, options, form));
      },
      { write: true, callOptions: options },
    );
  }
}

class TemplatesNamespace {
  constructor(private readonly api: TemplatesApi) {}

  get(id: string, options: ReadOptions = {}) {
    return withRetries(() => this.api.templatesGet({ id }, callInit(undefined, options)));
  }

  create(body: CreateTemplateInput, options: CallOptions = {}) {
    return withRetries(
      (key) => this.api.templatesCreate({ createTemplateInput: body }, callInit(key, options)),
      { write: true, callOptions: options },
    );
  }

  validate(body: CreateTemplateInput, options: CallOptions = {}) {
    return withRetries(
      (key) => this.api.templatesValidate({ createTemplateInput: body }, callInit(key, options)),
      { write: true, callOptions: options },
    );
  }

  update(id: string, body: UpdateTemplateInput, options: CallOptions = {}) {
    return withRetries(
      (key) => this.api.templatesUpdate({ id, updateTemplateInput: body }, callInit(key, options)),
      { write: true, callOptions: options },
    );
  }

  list(query: TemplateListQuery = {}, options: ReadOptions = {}): Promise<TemplateList> {
    return withRetries(() =>
      this.api.templatesList(templateQuery(query), callInit(undefined, options)),
    );
  }

  /** Pages on the caller's behalf; a cursor never reaches them. The timeout is per page. */
  async *listAll(
    query: Omit<TemplateListQuery, "startingAfter"> = {},
    options: ReadOptions = {},
  ): AsyncGenerator<Template> {
    const base = templateQuery(query);
    let startingAfter: string | undefined;
    for (;;) {
      const page = await withRetries(() =>
        this.api.templatesList({ ...base, startingAfter }, callInit(undefined, options)),
      );
      for (const item of page.data) yield item;
      const last = page.data.at(-1);
      if (!page.hasMore || !last) return;
      startingAfter = last.id;
    }
  }
}
