import { AsyncLocalStorage } from "node:async_hooks";
import { randomUUID } from "node:crypto";
import { APIConnectionError, APIError, toMsgEasyError, ValidationError } from "./errors.js";

/**
 * Which attempt is in flight, for the observability hook.
 *
 * The retry loop is here and the recording is around `fetch`, with the generated
 * core in between — so the number is carried out of band rather than threaded
 * through it. A header would reach the server, which is not the SDK's to spend.
 */
export const attemptStore = new AsyncLocalStorage<number>();

/** Both SDKs share these, or they are not interchangeable. */
export const DEFAULT_TIMEOUT_MS = 30_000;
export const MAX_ATTEMPTS = 3;
const BACKOFF_MS = [500, 1_000];

/** The API's own cap. Refused here so a typo costs no round trip. */
const MAX_IDEMPOTENCY_KEY_LENGTH = 255;

/** Codes that clear on their own. Everything else the caller must act on. */
const RETRYABLE_CODES = new Set(["rate_limited", "service_unavailable"]);

/** Only the in-progress variant. The wrong-body variant needs a different key, not a wait. */
function isRetryableConflict(error: APIError): boolean {
  return error.code === "idempotency_conflict" && error.retryAfterSeconds !== null;
}

/**
 * Stated rather than emergent: a connection failure may not have run at all and the
 * retry replays under the same key, while a `BadEnvelopeError` means something that
 * is not the API answered and waiting will not change that.
 */
function shouldRetry(error: unknown): boolean {
  if (error instanceof APIConnectionError) return true;
  if (error instanceof APIError) {
    return RETRYABLE_CODES.has(error.code) || isRetryableConflict(error);
  }
  return false;
}

/** `Retry-After` wins when the API sent one; jitter keeps retries from lining up. */
function waitFor(error: unknown, attempt: number): number {
  if (error instanceof APIError && error.retryAfterSeconds !== null) {
    return error.retryAfterSeconds * 1_000;
  }
  const base = BACKOFF_MS[attempt] ?? BACKOFF_MS[BACKOFF_MS.length - 1] ?? 1_000;
  return base + Math.random() * base * 0.25;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * Runs one call, retrying what clears on its own. Every failure is converted to a
 * typed error first, so the retry decision is made on the type and `code`, never on
 * the status.
 */
export async function withRetries<T>(
  call: (idempotencyKey?: string) => Promise<T>,
  options: { write?: boolean; callOptions?: CallOptions } = {},
): Promise<T> {
  // Minted once per call, not per attempt: a fresh key on a retry would make the
  // server treat it as a new request, which is the whole point of sending one.
  // A caller's own key is kept, so they can replay this exact send later.
  const supplied = options.callOptions?.idempotencyKey;
  if (supplied !== undefined) {
    // Refused rather than replaced. An empty string is almost always an unset
    // variable, and minting one instead would leave the caller believing they
    // hold a key they can replay.
    if (supplied === "") throw new ValidationError("idempotencyKey must not be empty.");
    if (supplied.length > MAX_IDEMPOTENCY_KEY_LENGTH) {
      throw new ValidationError(
        `idempotencyKey must be ${MAX_IDEMPOTENCY_KEY_LENGTH} characters or fewer, got ${supplied.length}.`,
      );
    }
  }
  const key = options.write ? (supplied ?? randomUUID()) : undefined;

  let last: unknown;
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt += 1) {
    try {
      return await attemptStore.run(attempt + 1, () => call(key));
    } catch (raw) {
      last = await toMsgEasyError(raw);
      if (attempt === MAX_ATTEMPTS - 1 || !shouldRetry(last)) throw last;
      await sleep(waitFor(last, attempt));
    }
  }
  throw last;
}

/**
 * What a read takes. No idempotency key: a `GET` sends none, so offering one would
 * be a silently ignored argument rather than an option.
 */
export interface ReadOptions {
  /** Replaces the client's timeout for this call. */
  timeoutMs?: number;
}

/** Per-call overrides of the client's own settings. */
export interface CallOptions extends ReadOptions {
  /** Your own key, to replay this exact write later. Reads send none. */
  idempotencyKey?: string;
}

/**
 * Wraps fetch with the client deadline. A signal already on the init is a per-call
 * timeout, and takes precedence.
 */
export function timedFetch(timeoutMs: number): typeof fetch {
  return async (input, init) => {
    if (init?.signal) return fetch(input, init);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      return await fetch(input, { ...init, signal: controller.signal });
    } finally {
      clearTimeout(timer);
    }
  };
}

/**
 * The generated runtime spreads `initOverrides` over its own init, so a plain object
 * would replace every configured header. The function form is handed the init to
 * merge into.
 */
export function callInit(key?: string, options: ReadOptions = {}, body?: BodyInit) {
  return async ({ init }: { init: RequestInit }): Promise<RequestInit> => ({
    headers: {
      ...(init.headers as Record<string, string>),
      ...(key ? { "Idempotency-Key": key } : {}),
    },
    // Built per attempt, so a retry gets the full timeout rather than what was left of it.
    ...(options.timeoutMs === undefined ? {} : { signal: AbortSignal.timeout(options.timeoutMs) }),
    // Only media sends one: the generated core appends the file unnamed, and this
    // replaces that body with a named one.
    ...(body === undefined ? {} : { body }),
  });
}
