/**
 * Replaced at build time from `package.json` (see `tsup.config.ts`), so the
 * version lives in exactly one place.
 *
 * The guard is for running the source unbundled — `tsx`, or an editor — where
 * nothing performs the substitution. It reports a dev marker rather than a
 * plausible-looking version, so a stray `0.0.0` in a support ticket is impossible.
 */
declare const __SDK_VERSION__: string | undefined;

export const VERSION = typeof __SDK_VERSION__ === "string" ? __SDK_VERSION__ : "0.0.0-dev";
